package rrpitTransport

import (
	"github.com/v2fly/v2ray-core/v5/common"
	"github.com/v2fly/v2ray-core/v5/transport/internet"
)

const protocolName = "rrpit"

func init() {
	common.Must(internet.RegisterProtocolConfigCreator(protocolName, func() interface{} {
		return new(Config)
	}))
}
syntax = "proto3";

package v2ray.core.transport.internet.rrpit.transport;
option csharp_namespace = "V2Ray.Core.Transport.Internet.Rrpit.Transport";
option go_package = "github.com/v2fly/v2ray-core/v5/transport/internet/rrpit/rrpitTransport";
option java_package = "com.v2ray.core.transport.internet.rrpit.transport";
option java_multiple_files = true;

import "google/protobuf/any.proto";

import "common/protoext/extensions.proto";
import "transport/internet/dtls/config.proto";

message DTLSUDPChannel {
  bytes ip = 1;
  uint32 port = 2;
  string password = 3;
  // If positive, consider this DTLS channel dead when no inbound rrpit message bytes arrive for this duration.
  int64 no_incoming_message_timeout = 4;
  v2ray.core.transport.internet.dtls.DTLSCipherSuite cipher_suite = 5;

  // Number of DTLS records retained by the anti-replay bitmap. Zero uses the
  // transport default. This must cover packet reordering caused by path jitter
  // at the configured packet rate, otherwise valid records are discarded
  // before RRIPT's FEC/reordering layer can see them.
  uint32 replay_protection_window = 6;

  string ip_addr = 68000 [(v2ray.core.common.protoext.field_opt).convert_time_parse_ip = "ip"];
}

message Channel {
  // Underlying channel transport settings, for example DTLSUDPChannel.
  ChannelSetting setting = 1;
  google.protobuf.Any channel = 2;
}

message ChannelSetting {
  // Maximum transmission unit of the underlying channel, in bytes.
  uint32 mtu = 1;

  // Relative scheduling weight of this channel. Zero means the default weight.
  int32 weight = 2;

  // Maximum packets this channel may send in a single rrpit timestamp window.
  int32 max_sending_speed = 3;

  // Number of packets that may wait for this channel's dedicated DTLS writer.
  // A positive value moves encryption and the UDP write to a per-channel
  // worker, allowing multiple physical channels to send concurrently. Zero
  // keeps synchronous writes.
  uint32 send_queue_capacity = 4;
}

message LaneSetting {
  // Size of each shard carried inside a transfer lane, in bytes.
  int32 shard_size = 1;

  // Maximum number of source data shards before a lane is finalized.
  int32 max_data_shards_per_lane = 2;

  // Maximum number of in-flight / buffered lanes kept by tx and rx state.
  int32 max_buffered_lanes = 3;

  // Remote sender's maximum number of source data shards per lane. Zero disables the heuristic.
  int32 remote_max_data_shards_per_lane = 4;
}

message SessionReconstructionSetting {
  // the fraction of repair share (compare to data shards) to send immediately after finishing sending the data.
  float initial_repair_shard_ratio = 1;

  // when there is still sending capacity in channels, send repair shards for each lane depending on this weight,
  // and number of repair shards still missing(known from control message)
  repeated float lane_repair_weight = 2;

  // when we received acknowledgement from remote, the fraction of repair shard to send compared to data shards missing
  float secondary_repair_shard_ratio = 3;

  // the number of tickets before we send the secondary repair shard again
  int32 time_resend_secondary_repair_shard = 4;

  // Number of ticks a finalized oldest lane may stay incomplete before stale-lane boost activates.
  int32 stale_lane_finalized_age_threshold_ticks = 5;

  // Number of ticks the oldest finalized lane may make no progress before stale-lane boost activates.
  int32 stale_lane_progress_stall_threshold_ticks = 6;

  // Minimum number of repair shards in a normal secondary resend burst.
  int32 secondary_repair_min_burst = 7;

  bool always_restrict_source_data_when_oldest_lane_stalled = 8;

  // Minimum ticks between opportunistic lane-weight repairs. Initial and
  // explicitly scheduled feedback repairs are never delayed. Zero or one
  // preserves the legacy every-tick behavior.
  int32 opportunistic_repair_interval_ticks = 9;
}

message SessionManagerSetting {
  // Tick interval, int64 values of time.Duration.
  int64 timestamp_interval = 1;

  int32 interactive_primary_cancellation_counter_limit = 2;

  int32 manager_hosted_control_keepalive_interval_ticks = 3;

  bool dynamic_restrict_source_data_when_oldest_lane_stalled = 4;

  int32 dynamic_restrict_source_data_when_oldest_lane_stalled_ticks = 5;
}

message SessionSetting {
  // Whether locally assigned tx channel ids should use odd parity.
  bool odd_channel_ids = 1;

  // Rewind window for tx-side packet timestamp history.
  int32 max_rewindable_timestamp_num = 2;

  // Rewind window for tx-side remote control history.
  int32 max_rewindable_control_message_num = 3;

  SessionReconstructionSetting reconstruction = 5;
}

// Per-traffic-class overrides. Shard size remains shared because every class
// uses the same materialized channels and PMTU.
message SessionClassSetting {
  int32 max_data_shards_per_lane = 1;
  int32 max_buffered_lanes = 2;
  int32 remote_max_data_shards_per_lane = 3;
  SessionReconstructionSetting reconstruction = 4;
}

message EngineeringSetting {
  // If non-empty, rrpit debug snapshots and packet logs are written here.
  string debugger_dir = 1;

  // Maximum bytes per rotated debugger packet log file.
  int64 debugger_max_file_size_bytes = 2;

  // Maximum number of rotated debugger packet log files retained.
  int32 debugger_max_files = 3;
}

message AdaptorSetting {
  // SMUX protocol version. Zero means the smux default.
  int32 smux_version = 1;

  // Disable smux keep-alive probes.
  bool keep_alive_disabled = 2;

  // Keep-alive interval, int64 values of time.Duration. Zero means the smux default.
  int64 keep_alive_interval = 3;

  // Keep-alive timeout, int64 values of time.Duration. Zero means the smux default.
  int64 keep_alive_timeout = 4;

  // Maximum smux frame size in bytes. Zero means the smux default.
  int32 max_frame_size = 5;

  // Maximum total smux receive buffer in bytes. Zero means the smux default.
  int32 max_receive_buffer = 6;

  // Maximum per-stream smux receive buffer in bytes. Zero means the smux default.
  int32 max_stream_buffer = 7;

  // Maximum consecutive interactive-session SMUX frames in one RRIPT message.
  // Zero or one disables aggregation.
  int32 aggregation_max_frames = 8;

  // Queue depth required before frames are aggregated. Below the threshold,
  // frames are flushed individually after aggregation_flush_delay.
  int32 aggregation_min_queue_frames = 9;

  // Maximum aggregation hold time, encoded as an int64 time.Duration.
  int64 aggregation_flush_delay = 10;
}

message ConnectionPersistenceSetting {
  // How long to retain a logical rrpit session after all DTLS channels are gone. Zero closes immediately.
  int64 disconnected_session_retention = 1;

  // Client reconnect retry interval while the logical session is retained. Zero means use the transport default.
  int64 reconnect_retry_interval = 2;

  // Keep the client rrpit transport session open even when there are no proxied streams.
  bool keep_transport_session_without_streams = 3;

  // Idle timeout when keep_transport_session_without_streams is false. Zero means use the transport default.
  int64 idle_timeout = 4;

  // If positive, discard the local cached rrpit session when no remote control packet is received within this duration.
  int64 remote_control_inactivity_timeout = 5;
}

message Config {
  option (v2ray.core.common.protoext.message_opt).type = "transport";
  option (v2ray.core.common.protoext.message_opt).short_name = "rrpit";
  option (v2ray.core.common.protoext.message_opt).allow_restricted_mode_load = false;

  repeated Channel channels = 1;
  LaneSetting lane = 2;
  SessionSetting session = 3;
  EngineeringSetting engineering = 4;
  AdaptorSetting adaptor = 5;
  SessionManagerSetting session_mgr = 6;
  ConnectionPersistenceSetting persistence = 7;
  SessionClassSetting interactive_session = 8;
  SessionClassSetting background_session = 9;
}

